import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadBengaliData(){const e=readFileSync(resolve(__dirname,"../../bengali-cinema-explorer/script.js"),"utf-8").replace(/document\.addEventListener\("app:route-changed"[\s\S]*$/,"");return new Function(e+"\nreturn { BENGALI_CINEMA_INFO, BENGALI_FILMS, BENGALI_FILMMAKERS, BENGALI_TIMELINE, BENGALI_GALLERY, BENGALI_REFERENCES };")()}describe("Bengali Cinema Explorer — Data Integrity",()=>{let e;beforeAll(()=>{e=loadBengaliData()}),describe("BENGALI_CINEMA_INFO metadata",()=>{it("contains correct id and name",()=>{expect(e.BENGALI_CINEMA_INFO.id).toBe("bengali-cinema"),expect(e.BENGALI_CINEMA_INFO.name).toContain("Bengali")}),it("identifies correct language and region",()=>{expect(e.BENGALI_CINEMA_INFO.language).toBe("Bengali"),expect(e.BENGALI_CINEMA_INFO.region).toContain("West Bengal")}),it("references Eighth Schedule correctly",()=>{expect(e.BENGALI_CINEMA_INFO.schedule).toContain("Eighth Schedule")}),it("has at least 3 cultural roots listed",()=>{expect(Array.isArray(e.BENGALI_CINEMA_INFO.culturalRoots)).toBe(!0),expect(e.BENGALI_CINEMA_INFO.culturalRoots.length).toBeGreaterThanOrEqual(3)})}),describe("BENGALI_FILMS dataset",()=>{it("contains exactly 6 notable film entries",()=>{expect(Array.isArray(e.BENGALI_FILMS)).toBe(!0),expect(e.BENGALI_FILMS.length).toBe(6)}),it("every film entry has required fields: id, title, year, genre, significance",()=>{e.BENGALI_FILMS.forEach((e,t)=>{expect(e,`Film ${t} missing id`).toHaveProperty("id"),expect(e,`Film ${t} missing title`).toHaveProperty("title"),expect(e,`Film ${t} missing year`).toHaveProperty("year"),expect(e,`Film ${t} missing genre`).toHaveProperty("genre"),expect(e,`Film ${t} missing significance`).toHaveProperty("significance"),expect(typeof e.title).toBe("string"),expect(e.title.trim().length).toBeGreaterThan(0),expect(typeof e.year).toBe("number")})}),it("first film is from 1955 (Pather Panchali)",()=>{const t=e.BENGALI_FILMS[0];expect(t.year).toBe(1955),expect(t.title).toBe("Pather Panchali")}),it("films are in chronological order",()=>{for(let t=0;t<e.BENGALI_FILMS.length-1;t++)expect(e.BENGALI_FILMS[t].year).toBeLessThanOrEqual(e.BENGALI_FILMS[t+1].year)})}),describe("BENGALI_FILMMAKERS dataset",()=>{it("contains at least 4 legendary filmmakers",()=>{expect(Array.isArray(e.BENGALI_FILMMAKERS)).toBe(!0),expect(e.BENGALI_FILMMAKERS.length).toBeGreaterThanOrEqual(4)}),it("every filmmaker has id, name, role, and contribution fields",()=>{e.BENGALI_FILMMAKERS.forEach((e,t)=>{expect(e,`Filmmaker ${t} missing id`).toHaveProperty("id"),expect(e,`Filmmaker ${t} missing name`).toHaveProperty("name"),expect(e,`Filmmaker ${t} missing role`).toHaveProperty("role"),expect(e,`Filmmaker ${t} missing contribution`).toHaveProperty("contribution"),expect(typeof e.name).toBe("string"),expect(e.name.trim().length).toBeGreaterThan(0)})}),it("includes Satyajit Ray as a key director",()=>{const t=e.BENGALI_FILMMAKERS.find(e=>e.name.includes("Satyajit Ray"));expect(t).toBeDefined(),expect(t.role).toContain("Director")})}),describe("BENGALI_TIMELINE dataset",()=>{it("contains exactly 5 timeline eras",()=>{expect(Array.isArray(e.BENGALI_TIMELINE)).toBe(!0),expect(e.BENGALI_TIMELINE.length).toBe(5)}),it("every timeline entry has id, period, era, and description",()=>{e.BENGALI_TIMELINE.forEach((e,t)=>{expect(e,`Timeline ${t} missing id`).toHaveProperty("id"),expect(e,`Timeline ${t} missing period`).toHaveProperty("period"),expect(e,`Timeline ${t} missing era`).toHaveProperty("era"),expect(e,`Timeline ${t} missing description`).toHaveProperty("description"),expect(typeof e.era).toBe("string"),expect(e.era.trim().length).toBeGreaterThan(0)})}),it("first era is the 1910s-1920s silent era",()=>{expect(e.BENGALI_TIMELINE[0].period).toContain("1910")}),it("last era references modern digital or literary resurgence",()=>{const t=e.BENGALI_TIMELINE[e.BENGALI_TIMELINE.length-1];expect(t.description).toMatch(/digital|literary|resurgence/i)})}),describe("BENGALI_GALLERY dataset",()=>{it("has exactly 4 gallery items",()=>{expect(Array.isArray(e.BENGALI_GALLERY)).toBe(!0),expect(e.BENGALI_GALLERY.length).toBe(4)}),it("every gallery item has id, title, and subtitle",()=>{e.BENGALI_GALLERY.forEach((e,t)=>{expect(e,`Gallery ${t} missing id`).toHaveProperty("id"),expect(e,`Gallery ${t} missing title`).toHaveProperty("title"),expect(e,`Gallery ${t} missing subtitle`).toHaveProperty("subtitle")})})}),describe("BENGALI_REFERENCES dataset",()=>{it("contains at least 4 references",()=>{expect(Array.isArray(e.BENGALI_REFERENCES)).toBe(!0),expect(e.BENGALI_REFERENCES.length).toBeGreaterThanOrEqual(4)}),it("every reference has id, source, and title",()=>{e.BENGALI_REFERENCES.forEach((e,t)=>{expect(e,`Reference ${t} missing id`).toHaveProperty("id"),expect(e,`Reference ${t} missing source`).toHaveProperty("source"),expect(e,`Reference ${t} missing title`).toHaveProperty("title")})}),it("includes Satyajit Ray as a reference source",()=>{const t=e.BENGALI_REFERENCES.find(e=>e.source.includes("Satyajit Ray"));expect(t).toBeDefined()})})});